    ('Colorama', 'Colorama Pro', 'Pinturas', 'Pinturas especiales', 'Pintura para Tableros', 'Pintura mate para tableros escolares y de oficina. Permite escribir con marcador y borrar sin manchar.', true, false, NULL),
    ('Colorama', 'Colorama Hogar', 'Preparación de superficies', 'Estucos y masillas', 'Estuco Plástico Interiores', 'Estuco listo para usar que alisa muros y techos interiores antes de pintar. Lijado fácil.', true, false, 'Herramientas y accesorios'),
    ('Colorama', 'Colorama Pro', 'Preparación de superficies', 'Estucos y masillas', 'Masilla Acrílica para Exteriores', 'Masilla para reparar fisuras y huecos en fachadas. Resiste humedad y no se agrieta.', false, true, 'Herramientas y accesorios'),
    ('Colorama', 'Colorama Pro', 'Preparación de superficies', 'Selladores e imprimantes', 'Sellador Acrílico para Muros', 'Sella el poro del muro y mejora la adherencia y el rendimiento de la pintura de acabado.', true, true, 'Pinturas'),
    ('Colorama', 'Colorama Pro', 'Preparación de superficies', 'Removedores y limpiadores', 'Removedor de Pintura en Gel', 'Gel removedor para quitar capas de pintura y barniz de madera y metal sin dañar la superficie.', true, true, NULL),
    ('Maderplus', 'Maderplus Exterior', 'Maderas', 'Barnices', 'Barniz Marino Brillante', 'Barniz marino de alta protección UV para madera expuesta al sol, la lluvia y la humedad.', true, true, 'Herramientas y accesorios'),
    ('Maderplus', 'Maderplus Exterior', 'Maderas', 'Lacas', 'Laca Catalizada Brillante', 'Laca de dos componentes para muebles y puertas: película dura, brillante y resistente a los rayones.', true, false, NULL),
    ('Maderplus', 'Maderplus Exterior', 'Maderas', 'Tintes e inmunizantes', 'Tinte para Madera', 'Tinte penetrante que realza la veta de la madera. Disponible en cinco tonos de madera natural.', true, false, 'Maderas'),
    ('Impermax', 'Impermax Techos', 'Impermeabilizantes', 'Techos y cubiertas', 'Impermeabilizante Acrílico para Terrazas', 'Membrana líquida acrílica para terrazas y cubiertas. Elástica, transitable y fácil de aplicar con brocha o rodillo.', false, true, 'Herramientas y accesorios'),
    ('Impermax', 'Impermax Techos', 'Impermeabilizantes', 'Muros y fachadas', 'Impermeabilizante para Muros', 'Protege muros y fachadas contra la humedad por filtración y capilaridad. Transpirable.', true, true, 'Pinturas'),
    ('Impermax', 'Impermax Techos', 'Impermeabilizantes', 'Siliconas y sellos de juntas', 'Silicona Sello de Juntas', 'Silicona neutra para sellar juntas, marcos de ventana y uniones. Flexible y resistente a la intemperie.', true, true, NULL),
    ('Colorama', 'Colorama Hogar', 'Aerosoles', 'Aerosoles multisuperficie', 'Aerosol Multisuperficie', 'Pintura en aerosol de secado rápido para metal, madera, plástico y cerámica. Cinco colores de fábrica.', true, true, NULL),
    ('Colorama', 'Colorama Pro', 'Aerosoles', 'Aerosoles especiales', 'Aerosol Alta Temperatura', 'Esmalte en aerosol resistente a altas temperaturas para estufas, parrillas, motores y escapes.', true, true, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Brochas', 'Brocha Profesional de 3 Pulgadas', 'Brocha de cerda sintética con mango de madera. No suelta pelo y deja un acabado parejo.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Brochas', 'Brocha Angular para Cortes', 'Brocha angular para cortar bordes, marcos y esquinas con precisión.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Rodillos', 'Rodillo de Felpa de 9 Pulgadas', 'Rodillo de felpa media para muros lisos y semirrugosos, con armazón reforzado.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Rodillos', 'Mini Rodillo de Espuma', 'Mini rodillo de espuma para puertas, muebles y detalles. Acabado liso sin burbujas.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Bandejas y extensiones', 'Bandeja para Rodillo', 'Bandeja plástica con rampa para cargar y escurrir el rodillo. Fácil de limpiar.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Bandejas y extensiones', 'Extensión Telescópica para Rodillo', 'Extensión metálica de 1 a 2 metros para pintar techos y muros altos sin escalera.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Cintas y protección', 'Cinta de Enmascarar', 'Cinta de papel crepé para proteger bordes y marcos. Se retira limpio sin dejar residuos.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Lijas y espátulas', 'Lija de Agua Grano 220', 'Lija al agua para acabados finos en madera, metal y estuco. Hoja de alta duración.', false, false, NULL),
    ('Goya', NULL, 'Herramientas y accesorios', 'Lijas y espátulas', 'Espátula de Acero de 3 Pulgadas', 'Espátula de hoja flexible para aplicar estuco y masilla y raspar superficies.', false, false, NULL)
) AS v(marca, linea, categoria, subcategoria, nombre, descripcion, interior, exterior, complementaria)
JOIN marca m ON m.nombre = v.marca
LEFT JOIN linea l ON l.id_marca = m.id_marca AND l.nombre = v.linea
JOIN categoria c ON c.nombre = v.categoria
JOIN subcategoria sc ON sc.id_categoria = c.id_categoria AND sc.nombre = v.subcategoria
LEFT JOIN categoria cc ON cc.nombre = v.complementaria
ON CONFLICT DO NOTHING;

