-- 9. Una ilustración principal por producto (solo si todavía no tiene imagen principal)
INSERT INTO imagen (id_producto, datos, mime_type, orden, es_principal)
SELECT p.id_producto, decode('', 'base64'), 'image/webp', 0, true
FROM producto p JOIN marca m ON m.id_marca = p.id_marca
WHERE m.nombre = 'Pintuco' AND p.nombre = 'Viniltex Advanced Mate'
  AND NOT EXISTS (SELECT 1 FROM imagen i WHERE i.id_producto = p.id_producto AND i.es_principal);

