-- 10. Historial de ventas de ejemplo (42 órdenes DEMO-xxxx de los últimos 75 días). Alimenta «Los más vendidos» y los
--     paneles del administrador. Se asignan a los clientes que ya existan; si no hay ninguno, o si ya se cargaron, no se hace nada.
DO $demo$
DECLARE
  v_clientes INT[];
  v_orden INT;
BEGIN
  SELECT array_agg(u.id_usuario ORDER BY u.id_usuario) INTO v_clientes
  FROM usuario u JOIN rol r ON r.id_rol = u.id_rol
  WHERE r.nombre = 'cliente' AND u.estado = 'activo';

  IF v_clientes IS NULL THEN
    RAISE NOTICE 'No hay clientes activos: se omite el historial de ventas de ejemplo.';
    RETURN;
  END IF;
  IF EXISTS (SELECT 1 FROM orden WHERE codigo_visible LIKE 'DEMO-%') THEN
    RAISE NOTICE 'El historial de ventas de ejemplo ya estaba cargado: no se repite.';
    RETURN;
  END IF;

  -- DEMO-0001 · entregado
  INSERT INTO orden (codigo_visible, id_usuario, origen, estado, modo_entrega, costo_entrega, sub_total, descuento, total, base_sin_impuesto, importe_iva, tasa_iva, observaciones, fecha)
  VALUES ('DEMO-0001', v_clientes[1 + (0 % array_length(v_clientes, 1))], 'carrito', 'entregado', 'recogida', 0, 81600, 0, 81600, 68571.43, 13028.57, 19, 'Orden de demostración', CURRENT_DATE - 33)
  RETURNING id_orden INTO v_orden;
    INSERT INTO linea_orden (id_orden, nombre_producto, variante_copia, precio_aplicado, cantidad, precio_inicial, id_variante_ref, sku_vendido)
    VALUES (v_orden, 'Estuco Plástico Interiores', '1 galón', 36900, 1, 36900, (SELECT id_variante FROM variante WHERE sku = 'COL-EST-GAL'), 'COL-EST-GAL');
    INSERT INTO linea_orden (id_orden, nombre_producto, variante_copia, precio_aplicado, cantidad, precio_inicial, id_variante_ref, sku_vendido)
    VALUES (v_orden, 'Viniltex Ultralavable', '1/4 de galón', 28900, 1, 28900, (SELECT id_variante FROM variante WHERE sku = 'VIN-ULT-QT'), 'VIN-ULT-QT');
    INSERT INTO linea_orden (id_orden, nombre_producto, variante_copia, precio_aplicado, cantidad, precio_inicial, id_variante_ref, sku_vendido)
    VALUES (v_orden, 'Cinta de Enmascarar', 'Rollo de 40 m', 7900, 2, 7900, (SELECT id_variante FROM variante WHERE sku = 'GOY-CIN-40'), 'GOY-CIN-40');
    INSERT INTO historial_estado_orden (id_orden, estado_anterior, estado_nuevo, id_usuario_autor, motivo, fecha)
    VALUES (v_orden, NULL, 'orden_confirmada', NULL, NULL, now() - interval '33 days' + interval '0 hours');
    INSERT INTO historial_estado_orden (id_orden, estado_anterior, estado_nuevo, id_usuario_autor, motivo, fecha)
    VALUES (v_orden, 'orden_confirmada', 'revision_disponibilidad', NULL, NULL, now() - interval '33 days' + interval '5 hours');
    INSERT INTO historial_estado_orden (id_orden, estado_anterior, estado_nuevo, id_usuario_autor, motivo, fecha)
    VALUES (v_orden, 'revision_disponibilidad', 'en_preparacion', NULL, NULL, now() - interval '33 days' + interval '10 hours');
    INSERT INTO historial_estado_orden (id_orden, estado_anterior, estado_nuevo, id_usuario_autor, motivo, fecha)
    VALUES (v_orden, 'en_preparacion', 'preparada', NULL, NULL, now() - interval '33 days' + interval '15 hours');
    INSERT INTO historial_estado_orden (id_orden, estado_anterior, estado_nuevo, id_usuario_autor, motivo, fecha)
    VALUES (v_orden, 'preparada', 'despachado', NULL, NULL, now() - interval '33 days' + interval '20 hours');
    INSERT INTO historial_estado_orden (id_orden, estado_anterior, estado_nuevo, id_usuario_autor, motivo, fecha)
    VALUES (v_orden, 'despachado', 'entregado', NULL, NULL, now() - interval '33 days' + interval '25 hours');

